#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
int main() {
  std::vector<std::string> words = {"a","b","a","c","b","a","d","b"};
  std::unordered_map<std::string,int> freq;
  for (auto& w : words) freq[w]++;
  std::vector<std::pair<std::string,int>> v(freq.begin(), freq.end());
  std::sort(v.begin(), v.end(), [](auto& x, auto& y){
    return x.second != y.second ? x.second > y.second : x.first < y.first;
  });
  for (size_t i = 0; i < std::min<size_t>(3, v.size()); ++i)
    std::cout << v[i].first << ':' << v[i].second << '\n';
}

void sortColors(vector<int>& a) {
  int lo = 0, mid = 0, hi = (int)a.size() - 1;
  while (mid <= hi) {
    if (a[mid] == 0) swap(a[lo++], a[mid++]);
    else if (a[mid] == 2) swap(a[mid], a[hi--]);
    else ++mid;
  }
}

vector<vector<int>> merge(vector<vector<int>>& iv) {
  sort(iv.begin(), iv.end(), [](auto& a, auto& b){ return a[0] < b[0]; });
  vector<vector<int>> ans;
  for (auto& cur : iv) {
    if (ans.empty() || cur[0] > ans.back()[1]) ans.push_back(cur);
    else ans.back()[1] = max(ans.back()[1], cur[1]);
  }
  return ans;
}
